\title[The Galois/Frobenius side channel]{The Galois/Frobenius Side Channel in Integer Factoring:\\ An Abelianization Cap, an Exact Symmetry Wall,\\ and a Frobenius One-Time Pad}
\author{Aristotle}
\date{October 16, 2026}

\begin{document}

\begin{abstract}
Let $N=pq$ be a product of two unknown primes and $K/\Q$ a fixed finite Galois extension with group $G$. The Frobenius elements $\sigma_p,\sigma_q\in G$ govern how $p$ and $q$ split in $K$ and its subfields. Part of the Frobenius of $N$ can be computed from $N$ alone: its image in the abelianization $G/G'$, which by class field theory is determined by a congruence class of $N$. This \emph{Galois/Frobenius side channel} is a candidate attack primitive distinct from the classical families (congruences of squares, group orders, smoothness/index calculus, algebraic/complex-multiplication methods). We model Frobenius elements, via the Chebotarev density theorem, as uniform random group elements and work in the exact finite Shannon calculus. In this model the channel is closed in three independent ways. (1)~\emph{The abelianization cap}: the residue class of a Frobenius element shares at most $\log_2[G:G']$ bits with any readout of it, even after arbitrary post-processing of either side; for $S_4$ quartic fields (five splitting types) this is one bit, and for perfect groups it is zero. (2)~\emph{The symmetry wall}: whenever readout-preserving symmetries act transitively on a hidden label, the label is exactly uniform and the readout carries exactly zero bits about it; hence in every finite group every swap-invariant readout of a semiprime carries exactly $0$ of the $1$ bit saying which factor carries which splitting type, and exactly $0$ of $\log_2(m+1)$ bits for $m+1$ factors. (3)~\emph{The Frobenius one-time pad}: in any finite group, with $\sigma_p$ uniform on an arbitrary candidate set $A\subseteq G$ and $\sigma_q$ uniform on $G$, every readout of $\sigma_p\sigma_q$ is independent of every readout of $\sigma_p$, so the posterior equals the prior. Combining these yields a \emph{semiprime ledger}: the residue of $N$ is uniform on $G/G'$, blind to the type of each factor separately, carries the same information about the ordered and unordered type pair, and never exceeds $\log_2[G:G']$ bits. For $S_4$ it carries exactly $1$ bit and for $D_4$ exactly $\tfrac{39}{16}-\tfrac34\log_2 3+\tfrac{5}{64}\log_2 5\approx1.430$ bits about the unordered pair of types; all of it is purely synergistic.
\end{abstract}

\maketitle

\section{Introduction}

The security of RSA-type cryptosystems rests on the presumed hardness of recovering $p$ and $q$ from $N=pq$. Known factoring algorithms fall into four broad families: \emph{congruences of squares} (Dixon's method, the quadratic and number field sieves); \emph{group orders} (Pollard's $p-1$, Williams' $p+1$, Lenstra's elliptic curve method); \emph{smoothness and index calculus}; and \emph{algebraic and complex-multiplication structure}.

A natural fifth idea comes from algebraic number theory. Every prime $p$ unramified in a Galois extension $K/\Q$ has a Frobenius conjugacy class in $G=\mathrm{Gal}(K/\Q)$, which determines the splitting type of $p$ in every subfield of $K$, that is, the factorisation pattern of a defining polynomial modulo $p$. If some of $\sigma_p$ could be read from $N$, then each field would deliver some bits about $p$. We call this the \emph{Galois/Frobenius side channel}.

The visible part of the channel is abelian. Write $G'$ for the derived subgroup and $G^{\ab}=G/G'$. The fixed field $K^{G'}$ is the maximal abelian subextension. By the Kronecker--Weber theorem it lies in a cyclotomic field $\Q(\zeta_f)$, so the image of $\sigma_p$ in $G^{\ab}$ is a function of $p\bmod f$. Since the Artin map is a homomorphism, the coset $\sigma_p\sigma_qG'$ is a function of $N\bmod f$. We call it the \emph{residue} of $N$; it is computable without knowing $p$ or $q$.

We prove that the channel is closed in three independent senses. Section~\ref{sec:setting} sets up the model; Section~\ref{sec:cap} proves the abelianization cap; Section~\ref{sec:pad} proves the independence law and the Frobenius one-time pad; Section~\ref{sec:wall} proves the symmetry wall and the which-factor walls; Section~\ref{sec:ledger} assembles the semiprime ledger; Section~\ref{sec:alg} describes exact algorithms; Section~\ref{sec:disc} discusses what remains open.

\section{Setting}\label{sec:setting}

\subsection{Finite Shannon calculus}
A \emph{sample space} is a finite non-empty set $\Omega$ with the uniform probability measure. A \emph{readout} is any function $f:\Omega\to\alpha$. For $a\in\alpha$ the \emph{fibre} is $\Omega_{f=a}=\{\omega\in\Omega: f(\omega)=a\}$ and $\Pr[f=a]=|\Omega_{f=a}|/|\Omega|$.

\begin{definition}[Entropy, mutual information]
The \emph{entropy} of $f$ is $H(f)=-\sum_{a\in f(\Omega)}\Pr[f=a]\log_2\Pr[f=a]$. For readouts $f,g$ the \emph{joint readout} is $(f,g)(\omega)=(f(\omega),g(\omega))$, and the \emph{mutual information} is
\[ I(f;g)=H(f)+H(g)-H(f,g). \]
For a third readout $u$, the \emph{conditional mutual information} is $I(f;g\mid u)=\sum_v\Pr[u=v]\,I_{\Omega_{u=v}}(f;g)$, computed on each fibre with its own uniform measure.
\end{definition}

We use freely: $0\le I(f;g)\le\min(H(f),H(g))$; symmetry of $I$; $H(f)\le\log_2|f(\Omega)|$ with equality iff $f$ is uniform on its image; and the chain rule $I(k;(u,w))=I(k;u)+I(k;w\mid u)$. Mutual information depends only on the partitions of $\Omega$ induced by the readouts.

\subsection{The arithmetic model}
Let $K/\Q$ be finite Galois with group $G$, realised as a permutation group on the $n$ roots of a defining polynomial $F$ of some subfield. For an unramified prime $p$, the degrees of the irreducible factors of $F\bmod p$ are the cycle lengths of $\sigma_p$; this multiset is the \emph{splitting type} $T(\sigma_p)$. More generally a \emph{type readout} is any function $T:G\to\tau$. The conjugacy class of $\sigma_p$ (the \emph{Artin symbol}) is the readout $g\mapsto[g]$.

\begin{definition}[Coset readout]
Let $N\le G$. A readout $c:G\to\kappa$ is a \emph{coset readout} for $N$ if $c(g)=c(h)\iff g^{-1}h\in N$ for all $g,h\in G$. For $N=G'$ we call $c$ the \emph{residue readout}.
\end{definition}

\begin{assumption}[Chebotarev]
By the Chebotarev density theorem, Frobenius elements of primes are equidistributed in $G$ (the class $C$ has density $|C|/|G|$). We model the Frobenius of an unknown prime as a uniform random element of $G$, and those of distinct unknown primes as independent. All theorems are exact statements in this model.
\end{assumption}

For a semiprime the sample space is $G\times G$ (ordered pairs $(\sigma_p,\sigma_q)$) or a subset of it, and the residue of $N$ is $(x,y)\mapsto c(xy)$.

\section{Data processing and the abelianization cap}\label{sec:cap}

\begin{theorem}[Data processing]\label{thm:dp}
For readouts $f:\Omega\to\alpha$, $g:\Omega\to\beta$ and arbitrary $\psi:\alpha\to\gamma$, $\varphi:\beta\to\delta$, we have $I(\psi\circ f;\varphi\circ g)\le I(f;g)$.
\end{theorem}
\begin{proof}[Proof sketch]
By symmetry it suffices to treat one side. First, $I(g;\psi\circ f)\le I(g;(\psi\circ f,f))$, since by the chain rule the difference is a non-negative conditional mutual information. Second, $(\psi\circ f,f)$ and $f$ induce the same partition of $\Omega$, so $I(g;(\psi\circ f,f))=I(g;f)$.
\end{proof}

\begin{lemma}[Uniform residue]\label{lem:unif}
If $N\le G$ are finite groups and $c$ is a coset readout for $N$, then under the uniform measure on $G$ every fibre of $c$ has $|N|$ elements, and $H(c)=\log_2[G:N]$.
\end{lemma}
\begin{proof}[Proof sketch]
The fibre through $g$ is the coset $gN$ (Lagrange). Equal fibres mean $c$ is uniform on its $|G|/|N|$ values.
\end{proof}

\begin{theorem}[The abelianization cap]\label{thm:cap}
Let $G$ be a finite group with residue readout $c$. For every type readout $T$ and all post-processings $\psi,\varphi$,
\[ I(\psi\circ c;\varphi\circ T)\;\le\; I(c;T)\;\le\;\log_2[G:G']=\log_2|G^{\ab}|. \]
\end{theorem}
\begin{proof}[Proof sketch]
The first inequality is Theorem~\ref{thm:dp}; the second is $I(c;T)\le H(c)$ together with Lemma~\ref{lem:unif}.
\end{proof}

\begin{corollary}[Perfect groups leak nothing]
If $G'=G$ then $I(\psi\circ c;\varphi\circ T)=0$ for all $T,\psi,\varphi$.
\end{corollary}

\begin{proposition}[Attaining the cap]\label{prop:attain}
$I(c;T)=\log_2[G:G']$ if and only if $c=\phi\circ T$ on $G$ for some $\phi$.
\end{proposition}
\begin{proof}[Proof sketch]
$I(c;T)=H(c)-H(c\mid T)$ and $H(c)=\log_2[G:G']$; equality holds iff $H(c\mid T)=0$, i.e.\ $c$ is constant on every fibre of $T$.
\end{proof}

Since $ghg^{-1}h^{-1}\in G'$, cosets of $G'$ are unions of conjugacy classes, so the Artin symbol always attains the cap. Table~\ref{tab:prime} gives exact values.

