\section{The independence law and the Frobenius one-time pad}\label{sec:pad}

\begin{lemma}[Independence law]\label{lem:indep}
Let $f,g$ be readouts on $\Omega$.
\begin{enumerate}[label=(\alph*)]
\item If $\Pr[f=a,g=b]=\Pr[f=a]\Pr[g=b]$ for all $a\in f(\Omega)$, $b\in g(\Omega)$, then $I(f;g)=0$.
\item If $|\Omega_{f=a,g=b}|\cdot|\Omega|=|\Omega_{f=a}|\cdot|\Omega_{g=b}|$ for all such $a,b$, then $I(f;g)=0$.
\end{enumerate}
\end{lemma}
\begin{proof}[Proof sketch]
(a) Expand $H(f,g)$ over $f(\Omega)\times g(\Omega)$ and use $\log_2(xy)=\log_2x+\log_2y$ and that marginals sum to $1$; this gives $H(f,g)=H(f)+H(g)$. (b) Divide by $|\Omega|^2$.
\end{proof}

\begin{lemma}[Shear count]\label{lem:shear}
Let $G$ be a finite group, $A\subseteq G$, and $P,Q$ predicates on $G$. Then
\[ \bigl|\{(x,y)\in A\times G: P(x)\wedge Q(xy)\}\bigr|=|\{x\in A:P(x)\}|\cdot|\{z\in G:Q(z)\}|. \]
\end{lemma}
\begin{proof}[Proof sketch]
The map $(x,z)\mapsto(x,x^{-1}z)$ is a bijection from $\{x\in A: P(x)\}\times\{z\in G: Q(z)\}$ onto the left-hand set, with inverse $(x,y)\mapsto(x,xy)$.
\end{proof}

\begin{theorem}[The Frobenius one-time pad]\label{thm:pad}
Let $G$ be a finite group, abelian or not, and $A\subseteq G$ any candidate set. On $A\times G$ (so $\sigma_p$ is uniform on $A$ and $\sigma_q$ independently uniform on $G$), for arbitrary readouts $F,H$ of $G$,
\[ I\bigl(F(\sigma_p);H(\sigma_p\sigma_q)\bigr)=0. \]
\end{theorem}
\begin{proof}[Proof sketch]
Let $\alpha_a=|\{x\in A:F(x)=a\}|$ and $\beta_b=|\{z\in G:H(z)=b\}|$. Lemma~\ref{lem:shear} applied three times gives $|\{F=a,H=b\}|=\alpha_a\beta_b$, $|\{F=a\}|=\alpha_a|G|$, $|\{H=b\}|=|A|\beta_b$. Since $|A\times G|=|A||G|$, the counting form of Lemma~\ref{lem:indep} holds.
\end{proof}

Here $H$ may be the residue of $N$, the Artin symbol of $\sigma_p\sigma_q$, its cycle type, or $\sigma_p\sigma_q$ itself; $F$ may be the splitting type of $p$ or $\sigma_p$ itself.

\begin{corollary}[Posterior equals prior]
In the setting of Theorem~\ref{thm:pad}, for every attained value $b$ and every $a$,
$\Pr[F(\sigma_p)=a\mid H(\sigma_p\sigma_q)=b]=\Pr[F(\sigma_p)=a]$.
\end{corollary}

\begin{corollary}[No pruning]
For any target $\sigma\in G$ and candidate $x\in A$, the element $y=x^{-1}\sigma$ satisfies $xy=\sigma$. Hence every candidate survives the observation of $\sigma_p\sigma_q$, and the consistent set meets every conjugacy class that $A$ meets.
\end{corollary}

The support statement settled negatively the conjecture that a non-abelian Artin-symbol channel might prune candidates; the posterior-equals-prior statement is strictly stronger.

\begin{proposition}[The pad breaks when the cofactor is revealed]
Under the hypotheses of Theorem~\ref{thm:pad} with $A\neq\varnothing$, $I(\sigma_p;(\sigma_p\sigma_q,\sigma_q))=\log_2|A|$.
\end{proposition}
\begin{proof}[Proof sketch]
$(\sigma_p\sigma_q,\sigma_q)$ determines $\sigma_p=(\sigma_p\sigma_q)\sigma_q^{-1}$, so the channel equals $H(\sigma_p)=\log_2|A|$.
\end{proof}

\section{The symmetry wall}\label{sec:wall}

\begin{definition}[Label transitivity]
Readouts $w$ (label) and $k$ (readout) on $\Omega$: $w$ is \emph{$k$-label-transitive} if for all $a,b\in w(\Omega)$ there is a bijection $\pi$ of $\Omega$ with $k\circ\pi=k$ and $w(\pi\omega)=b\iff w(\omega)=a$.
\end{definition}

\begin{theorem}[The symmetry wall]\label{thm:wall}
If $w$ is $k$-label-transitive, then $I(w;k)=0$ and $H(w)=\log_2|w(\Omega)|$.
\end{theorem}
\begin{proof}[Proof sketch]
$\pi$ maps $\{w=a,k=c\}$ bijectively onto $\{w=b,k=c\}$, so within each $k$-fibre the label is uniform: $\Pr[w=a,k=c]\,|w(\Omega)|=\Pr[k=c]$. Summing over $c$ gives $\Pr[w=a]\,|w(\Omega)|=1$. Hence the joint law factors and Lemma~\ref{lem:indep}(a) applies.
\end{proof}

\begin{definition}
$H:G\to\kappa$ is a \emph{class function} if $H(ghg^{-1})=H(h)$ for all $g,h\in G$.
\end{definition}

\begin{proposition}\label{prop:class}
(i) Every residue readout is a class function, since $(ghg^{-1})^{-1}h=gh^{-1}g^{-1}h\in G'$. (ii) If $H$ is a class function then $H(yx)=H(xy)$, since $yx=x^{-1}(xy)x$.
\end{proposition}

Thus the residue of $N$, the Artin symbol of $\sigma_p\sigma_q$ and its cycle type are symmetric under $p\leftrightarrow q$, even for non-abelian $G$.

Let $T:G\to\tau$ take values in a totally ordered set and $A\subseteq G$ be finite. Put $\Omega_{A,T}=\{(x,y)\in A\times A:T(x)\neq T(y)\}$ and $b(x,y)=[T(x)<T(y)]$.

\begin{theorem}[The which-factor wall]\label{thm:which}
For any group $G$, finite $A\subseteq G$, and any readout $k$ on $\Omega_{A,T}$ with $k(y,x)=k(x,y)$: $I(b;k)=0$, and $H(b)=1$ whenever $\Omega_{A,T}\neq\varnothing$.
\end{theorem}
\begin{proof}[Proof sketch]
The swap preserves $\Omega_{A,T}$ and $k$ and flips $b$; apply Theorem~\ref{thm:wall}.
\end{proof}

\begin{corollary}
For a residue readout $c$ or a class function $H$, the readouts $(c(xy),\min(Tx,Ty),\max(Tx,Ty))$ and $(H(xy),\min(Tx,Ty),\max(Tx,Ty))$ carry exactly zero bits about $b$ on $\Omega_{G,T}$; whereas the ordered readout $(Tx,Ty)$ carries the full $H(b)$.
\end{corollary}

For $N=p_0\cdots p_m$ let $\Omega^{(m)}_{A,T}=\{x\in A^{m+1}: i\mapsto T(x_i)\text{ injective}\}$ and let $\mu(x)$ be the index of the smallest type.

\begin{theorem}[The multi-prime wall]
For every readout $k$ on $\Omega^{(m)}_{A,T}$ invariant under exchanging any two coordinates, $I(\mu;k)=0$, and $H(\mu)=\log_2(m+1)$ whenever $\Omega^{(m)}_{A,T}\neq\varnothing$.
\end{theorem}
\begin{proof}[Proof sketch]
The transposition $(i\,j)$ preserves $k$ and the space and carries the label class $i$ onto $j$; apply Theorem~\ref{thm:wall}.
\end{proof}

\section{The semiprime ledger}\label{sec:ledger}

On $G\times G$ let $\rho(x,y)=c(xy)$ be the residue of $N$.

\begin{theorem}[Uniform residue of $N$]\label{thm:resunif}
$H(\rho)=\log_2[G:G']$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:shear} with $A=G$, each fibre of $\rho$ has $|G|\,|G'|$ elements, and $\rho$ has $[G:G']$ values.
\end{proof}

\begin{theorem}[Semiprime abelianization cap]
For every readout $R$ of $(\sigma_p,\sigma_q)$, $I(\rho;R)\le\log_2[G:G']$.
\end{theorem}

\begin{theorem}[Pure synergy]\label{thm:synergy}
For every readout $F$ of a single Frobenius element, $I(\rho;F(\sigma_p))=0$ and $I(\rho;F(\sigma_q))=0$.
\end{theorem}
\begin{proof}[Proof sketch]
The first is Theorem~\ref{thm:pad} with $A=G$. The swap bijection of $G\times G$ exchanges $F(\sigma_p)$ and $F(\sigma_q)$ and preserves $\rho$ by Proposition~\ref{prop:class}; mutual information is invariant under bijections of the sample space.
\end{proof}

\begin{theorem}[Ordered equals unordered]\label{thm:ord}
Let $\Omega_0\subseteq G\times G$ be swap-closed, $k$ swap-invariant on $\Omega_0$, and $T$ any type readout into a totally ordered set. Then $I(k;(T\sigma_p,T\sigma_q))=I(k;\{T\sigma_p,T\sigma_q\})$.
\end{theorem}
\begin{proof}[Proof sketch]
The ordered pair induces the same partition as (unordered pair, $b$), so by the chain rule $I(k;\text{ord})=I(k;\text{unord})+I(k;b\mid\text{unord})$. On a fibre with equal types $b$ is constant; on a fibre with distinct types the swap preserves the fibre and $k$ and flips $b$, so Theorem~\ref{thm:wall} gives zero.
\end{proof}

\begin{corollary}
For every finite $G$, every class function $H$ and every $T$, $I(H(\sigma_p\sigma_q);(T\sigma_p,T\sigma_q))=I(H(\sigma_p\sigma_q);\{T\sigma_p,T\sigma_q\})$.
\end{corollary}

\begin{theorem}[$S_4$]
For $G=S_4$ on four roots, $T$ the cycle type and $c$ the sign coset:
$I(\rho;T\sigma_p)=I(\rho;T\sigma_q)=0$, $I(\rho;\{T\sigma_p,T\sigma_q\})=1$, and $I(\rho;R)\le1$ for every readout $R$.
\end{theorem}

\begin{theorem}[$D_4$]
For $G=D_4\le S_4$ (order $8$, $G'$ the centre of order $2$), $T$ the quartic cycle type:
$I(\rho;T\sigma_p)=I(\rho;T\sigma_q)=0$,
\[ I(\rho;\{T\sigma_p,T\sigma_q\})=\tfrac{39}{16}-\tfrac34\log_23+\tfrac{5}{64}\log_25\approx1.430>1, \]
and $I(\rho;R)\le2$ for every readout $R$.
\end{theorem}
\begin{proof}[Proof sketch of both]
Zeros: Theorem~\ref{thm:synergy}. Caps: Theorem~\ref{thm:resunif} with indices $2$ and $4$. Middle values: exact finite computation over $576$ and $64$ pairs; for $D_4$, $>1$ uses $\log_23<2$ and $\log_25>2$.
\end{proof}

Every bit the residue of $N$ reveals about the factorisation shape is \emph{synergistic}: invisible to any one-factor reader, silent on which factor carries which type, and at most $\log_2[G:G']$ in total.

\section{Algorithms}\label{sec:alg}

\paragraph{Exact channel evaluation.} Tabulate $n_f(a)$, $n_g(b)$, $n_{fg}(a,b)$ in one pass; compute $H(f)=\log_2|\Omega|-|\Omega|^{-1}\sum_a n_f(a)\log_2 n_f(a)$ (likewise $H(g)$, $H(f,g)$); return $H(f)+H(g)-H(f,g)$. An exact zero is certified by the integer identities $n_{fg}(a,b)|\Omega|=n_f(a)n_g(b)$ (Lemma~\ref{lem:indep}(b)). Cost $O(|\Omega|)$ plus $O(|f(\Omega)||g(\Omega)|)$.

\paragraph{Abelianization cap.} Enumerate $G$ by closure under generators, generate $G'$ from all commutators, represent $c(g)=\min_{n\in G'}gn$, and return $\log_2(|G|/|G'|)$; test attainment by Proposition~\ref{prop:attain}. For large permutation groups, Schreier--Sims methods compute $|G|$ and $|G'|$ in polynomial time.

\paragraph{Symmetry-wall certificate.} Given candidate bijections $\Pi$, keep those preserving $\Omega$ and $k$; form the graph on $w(\Omega)$ joining $a\to b$ if some kept $\pi$ maps $w^{-1}(a)$ onto $w^{-1}(b)$; if it is complete, conclude $I(w;k)=0$ and $H(w)=\log_2|w(\Omega)|$ by Theorem~\ref{thm:wall}, without computing a logarithm.

\paragraph{Representative numbers.} In $S_4$, for random $A$ with $|A|\in[2,9]$, all channels between readouts of $\sigma_p$ and readouts of $\sigma_p\sigma_q$ are exactly zero, and revealing $\sigma_q$ gives $\log_2|A|$. For $S_3,S_4,A_4,D_4$ the which-factor bit has entropy $1$, the residue or Artin class with unordered types gives $0$, and ordered types give $1$. In $S_4$ with three factors ($5256$ tuples), the label has $\log_23$ bits and residue plus multiset of types gives $0$.

\section{Discussion}\label{sec:disc}

\begin{table}[h]
\centering
\begin{tabular}{lll}
\toprule
closure & type of statement & mechanism\\
\midrule
Abelianization cap & upper bound & Lagrange: residue uniform on $[G:G']$ cosets\\
Which-factor / multi-prime wall & exact zero & label-transitive symmetry ($pq=qp$)\\
Frobenius one-time pad & exact independence & shear $(x,y)\mapsto(x,xy)$\\
\bottomrule
\end{tabular}
\end{table}

\paragraph{The seams.} (1) The cap bounds the residue content, not the full type: a readout not factoring through the abelianization coset is bounded only by $H(T)$, and a large non-abelian $G$ with large $\log_2[G:G']$ and a positive ordered-versus-unordered gap is not excluded in principle (though Theorem~\ref{thm:ord} forbids such a gap for swap-invariant readouts). (2) The wall assumes symmetry; a readout of an asymmetric side input is untouched, but none computable from $N$ is known. (3) The model assumes exactly uniform independent Frobenius elements; transfer to primes of a given size is an effective Chebotarev question, with explicit bounds known under the Generalized Riemann Hypothesis.

Any new method in this family must, as a conjunction, supply a readout of $p$ that (i)~does not factor through $G^{\ab}$, (ii)~breaks the $p\leftrightarrow q$ symmetry, and (iii)~yields more than $O(1)$ bits about which factor is which, all from $N$ alone. By the one-time pad, (i) alone is insufficient.

\paragraph{Classical shadow.} For $G=(\Z/f\Z)^\times$ the residue of $N$ is $N\bmod f$, and Theorem~\ref{thm:pad} reduces to the familiar fact that multiplication by a uniform unit is a one-time pad. The theorem says this survives verbatim in every finite group, for every readout and every candidate set.

\section{Future directions}

\begin{enumerate}[label=\arabic*.]
\item \textbf{Multi-prime one-time pad.} For $N=p_1\cdots p_k$ with Frobenius elements i.i.d.\ uniform on $G$, the coset of $\sigma_1\cdots\sigma_k$ in $G^{\ab}$ should share zero bits with every readout of any $k-1$ factors and at most $\log_2[G:G']$ with any readout of all $k$; the shear $(x_1,\dots,x_k)\mapsto(x_1,\dots,x_{k-1},x_1\cdots x_k)$ suggests an induction.
\item \textbf{Semiprime completeness criterion.} Conjecturally $I(c(\sigma_p\sigma_q);\{T\sigma_p,T\sigma_q\})=\log_2[G:G']$ iff $c=\phi\circ T$ on $G$. One direction follows from Theorem~\ref{thm:ord}; the converse needs a fibrewise analysis of equality in $I\le H$. The data are consistent: $S_3,S_4$ attain the cap; $D_4$ ($\approx1.430<2$) and $A_4$ do not.
\item \textbf{Effective transfer} of the exact zeros to primes of size $X$ under effective Chebotarev bounds.
\item \textbf{Beyond the abelianization}: characterise readouts computable from $N$ that are not class functions of $\sigma_p\sigma_q$.
\end{enumerate}

