"""Abelianization cap of a permutation group: enumerate G, generate the derived
subgroup from commutators, build the residue (coset) readout, and test attainment."""
from collections import Counter
from math import log2
from typing import Callable, Dict, Hashable, List, Sequence, Set, Tuple

Perm = Tuple[int, ...]


def mul(a: Perm, b: Perm) -> Perm:
    return tuple(a[i] for i in b)


def inv(a: Perm) -> Perm:
    r = [0] * len(a)
    for i, x in enumerate(a):
        r[x] = i
    return tuple(r)


def closure(gens: Sequence[Perm]) -> Set[Perm]:
    e = tuple(range(len(gens[0])))
    seen: Set[Perm] = {e}
    frontier: List[Perm] = [e]
    while frontier:
        nxt: List[Perm] = []
        for x in frontier:
            for g in gens:
                y = mul(x, g)
                if y not in seen:
                    seen.add(y)
                    nxt.append(y)
        frontier = nxt
    return seen


def cycle_type(p: Perm) -> Tuple[int, ...]:
    seen: Set[int] = set()
    out: List[int] = []
    for i in range(len(p)):
        if i not in seen:
            j, l = i, 0
            while j not in seen:
                seen.add(j)
                j = p[j]
                l += 1
            out.append(l)
    return tuple(sorted(out))


def mutual_info(space: Sequence[Perm], f: Callable[[Perm], Hashable], g: Callable[[Perm], Hashable]) -> float:
    def H(xs: List[Hashable]) -> float:
        n = len(xs)
        return -sum(c / n * log2(c / n) for c in Counter(xs).values())
    fs = [f(w) for w in space]
    gs = [g(w) for w in space]
    return H(fs) + H(gs) - H(list(zip(fs, gs)))


def abelianization_cap(gens: Sequence[Perm], T: Callable[[Perm], Hashable] = cycle_type) -> Dict[str, float]:
    G = closure(gens)
    D = closure([mul(mul(a, b), mul(inv(a), inv(b))) for a in G for b in G])
    c = lambda g: min(mul(g, n) for n in D)          # canonical coset representative
    space = sorted(G)
    i_ct = mutual_info(space, c, T)
    fibres: Dict[Hashable, Set[Perm]] = {}
    for g in space:
        fibres.setdefault(T(g), set()).add(c(g))
    return {"order": len(G), "index": len(G) // len(D), "cap_bits": log2(len(G) // len(D)),
            "I(c;T)": i_ct, "attained": float(all(len(s) == 1 for s in fibres.values()))}


if __name__ == "__main__":
    print("S4", abelianization_cap([(1, 0, 2, 3), (1, 2, 3, 0)]))   # cap 1, attained
    print("D4", abelianization_cap([(1, 2, 3, 0), (2, 1, 0, 3)]))   # cap 2, I ~ 1.656

"""Symmetry-wall certificate: prove I(label; readout) = 0 and H(label) = log2 #labels
exactly, by exhibiting readout-preserving bijections that act transitively on labels."""
from itertools import product
from typing import Callable, Dict, Hashable, List, Sequence, Set, Tuple, TypeVar

W = TypeVar("W")


def symmetry_wall_certificate(space: Sequence[W],
                              label: Callable[[W], Hashable],
                              readout: Callable[[W], Hashable],
                              moves: Sequence[Callable[[W], W]]) -> bool:
    """True iff for every ordered pair of label values (a, b) some move pi
    (1) maps the space bijectively to itself, (2) preserves the readout, and
    (3) carries the label class of a exactly onto the label class of b."""
    S: Set[W] = set(space)
    labels = sorted({label(w) for w in space}, key=repr)
    good: List[Callable[[W], W]] = []
    for pi in moves:
        img = [pi(w) for w in space]
        if set(img) == S and len(set(img)) == len(S) and all(readout(pi(w)) == readout(w) for w in space):
            good.append(pi)
    reach: Dict[Tuple[Hashable, Hashable], bool] = {}
    for a, b in product(labels, labels):
        cls_a = {w for w in space if label(w) == a}
        cls_b = {w for w in space if label(w) == b}
        reach[(a, b)] = a == b or any({pi(w) for w in cls_a} == cls_b for pi in good)
    return all(reach.values())


if __name__ == "__main__":
    # three "factors" with distinct types drawn from {0,...,4}; label = position of the min type;
    # readout = sorted multiset of types (symmetric). Moves = coordinate transpositions.
    space = [x for x in product(range(5), repeat=3) if len(set(x)) == 3]
    label = lambda x: x.index(min(x))
    readout = lambda x: tuple(sorted(x))
    def transp(i: int, j: int) -> Callable[[Tuple[int, ...]], Tuple[int, ...]]:
        def pi(x: Tuple[int, ...]) -> Tuple[int, ...]:
            y = list(x); y[i], y[j] = y[j], y[i]; return tuple(y)
        return pi
    moves = [transp(i, j) for i in range(3) for j in range(i + 1, 3)]
    print("wall certified:", symmetry_wall_certificate(space, label, readout, moves))  # True
